CREATE TABLE "category" (
  "cat_id" bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "cat_title" bytea NOT NULL DEFAULT '\x'::bytea,
  "cat_pages" integer NOT NULL DEFAULT 0,
  "cat_subcats" integer NOT NULL DEFAULT 0,
  "cat_files" integer NOT NULL DEFAULT 0,
  PRIMARY KEY ("cat_id")
);

CREATE TABLE "categorylinks" (
  "cl_from" bigint NOT NULL DEFAULT 0,
  "cl_sortkey" bytea NOT NULL DEFAULT '\x'::bytea,
  "cl_timestamp" timestamp(0) without time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "cl_sortkey_prefix" bytea NOT NULL DEFAULT '\x'::bytea,
  "cl_type" text NOT NULL DEFAULT 'page' CHECK ("cl_type" IN ('page', 'subcat', 'file')),
  "cl_collation_id" integer NOT NULL DEFAULT 0,
  "cl_target_id" numeric(20,0) NOT NULL,
  PRIMARY KEY ("cl_from", "cl_target_id")
);

CREATE TABLE "linktarget" (
  "lt_id" bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "lt_namespace" integer NOT NULL,
  "lt_title" bytea NOT NULL,
  PRIMARY KEY ("lt_id")
);

CREATE TABLE "page" (
  "page_id" bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "page_namespace" integer NOT NULL DEFAULT 0,
  "page_title" bytea NOT NULL DEFAULT '\x'::bytea,
  "page_is_redirect" smallint NOT NULL DEFAULT 0,
  "page_is_new" smallint NOT NULL DEFAULT 0,
  "page_random" double precision NOT NULL DEFAULT 0,
  "page_touched" bytea NOT NULL,
  "page_links_updated" bytea,
  "page_latest" bigint NOT NULL DEFAULT 0,
  "page_len" bigint NOT NULL DEFAULT 0,
  "page_content_model" bytea,
  "page_lang" bytea,
  PRIMARY KEY ("page_id")
);

CREATE TABLE "pagelinks" (
  "pl_from" bigint NOT NULL DEFAULT 0,
  "pl_from_namespace" integer NOT NULL DEFAULT 0,
  "pl_target_id" numeric(20,0) NOT NULL,
  PRIMARY KEY ("pl_from", "pl_target_id")
);

CREATE TABLE "redirect" (
  "rd_from" bigint NOT NULL DEFAULT 0,
  "rd_namespace" integer NOT NULL DEFAULT 0,
  "rd_title" bytea NOT NULL DEFAULT '\x'::bytea,
  "rd_interwiki" bytea,
  "rd_fragment" bytea,
  PRIMARY KEY ("rd_from")
);

CREATE TABLE "revision" (
  "rev_id" bigint NOT NULL,
  "rev_page" bigint NOT NULL,
  "rev_parent_id" bigint,
  "rev_timestamp" timestamp(0) without time zone NOT NULL,
  "rev_minor_edit" smallint NOT NULL DEFAULT 0,
  "rev_len" bigint,
  "rev_sha1" bytea,
  "rev_user_id" bigint,
  "rev_user_text" bytea,
  "rev_comment" text,
  "rev_content_model" bytea,
  PRIMARY KEY ("rev_id")
);

CREATE TABLE "site_stats" (
  "ss_row_id" bigint NOT NULL DEFAULT 0,
  "ss_total_edits" numeric(20,0),
  "ss_good_articles" numeric(20,0),
  "ss_total_pages" numeric(20,0),
  "ss_users" numeric(20,0),
  "ss_images" numeric(20,0),
  "ss_active_users" numeric(20,0),
  "ss_temp_users" numeric(20,0),
  "ss_active_temp_users" numeric(20,0),
  PRIMARY KEY ("ss_row_id")
);

CREATE TABLE "text" (
  "old_id" bigint NOT NULL,
  "old_text" text,
  PRIMARY KEY ("old_id")
);

